import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Testing and acceptance","description":"","frontmatter":{"pageId":"developers/testing","contentRevision":1},"headers":[],"relativePath":"en/developers/testing.md","filePath":"en/developers/testing.md"}'),s={name:"en/developers/testing.md"};function r(o,e,l,c,d,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="testing-and-acceptance" tabindex="-1">Testing and acceptance <a class="header-anchor" href="#testing-and-acceptance" aria-label="Permalink to &quot;Testing and acceptance&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>First reproduce the case and observe a failing targeted test, then make the minimal fix and rerun. Server tests use a real WebApplicationFactory; client-core tests talk to a test server. Full suite: dotnet test Rimlink.sln -nologo -v q.</p><p>Open returning is not proof that the peer attached: assert on received events. Measure deadlines with Stopwatch, not DateTime.UtcNow. For timing changes, repeat on Linux/two CPUs where available.</p><p>Verify game logic with isolated host/guest instances, separate savedata and a separate server/port. BridgeTools/RimBridge is an available development tool, not a release dependency. Record executed steps/results in the manual checklist; a written scenario alone is not PASS.</p><p>Wiki: test:checks → check:content → check:reference → check:drift -- --base &lt;commit&gt; → build → check:links, followed by real browser/search/mobile navigation.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Do not start another server against live data or stop someone else&#39;s game. Game instances may overwrite the shared Player.log. Never report an unrun check as successful.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./build">Building the project</a></li><li><a href="./contributing">Contributing and wiki maintenance</a></li><li><a href="./../admins/troubleshooting">Administrator troubleshooting</a></li></ul>',11)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
